            derived_ext = {"file": file_ext, "symbol": sym_ext, "package": pkg_ext}
            for e in b["extents"]:
                for p in e["paths"]:
                    if p not in snapshot_paths or p not in fp_set:
                        _add(faults, "ENUMERATION_BINDING_EXTENT_PATHS")
                if not C.equal_typed(e["paths"], derived_ext.get(e["kind"], [])):
